{
  "cards": {
    "cover": {
      "narration": "The Bali Six, 8 days from 12–19 Oct 2026, starting right here where the sun won't wait.",
      "headline": "Bali",
      "line": "Six travellers, five stops, one very good idea."
    },
    "critters": {
      "narration": "You spotted 9 forms out there and made friends with 4 new critters. Rise and shine, little locals.",
      "headline": "New neighbours",
      "line": "Nine forms counted, four brand new faces in the crew book."
    },
    "route": {
      "narration": "Seminyak to Ubud to Mount Batur to Amed to Nusa Penida, 214 km all in, and Made drove 180.2 of them like a dream.",
      "headline": "The long way round",
      "line": "Longest leg was Ubud to Amed, 84.6 km and 180 minutes, with Made at the wheel."
    },
    "awards": {
      "narration": "And now the bits of paper and glory I hand over with a little bow. Terima kasih (thank you), all of you.",
      "headline": "The crew honours",
      "line": "Every one of you earned a moment in the sun."
    },
    "receipt": {
      "narration": "The whole trip ran USD 6,980, which is USD 1,163 each, and you came in USD 460 under the USD 7,440 plan. I know a guy who calls that a win.",
      "headline": "Bali maths",
      "line": "Under budget, over memories. Settle up when you like, the island isn't going anywhere."
    },
    "got_away": {
      "narration": "One legendary critter stayed just out of reach. Dev missed it by a whisker, but it comes back May to September, so no hard feelings.",
      "headline": "The one that got away",
      "line": "Dev, it'll be back May to September. Bring a bigger smile next time."
    },
    "stamp": {
      "narration": "Here's the stamp for the passport. Bali goes on the pass, and the pass goes everywhere with you.",
      "headline": "Signed and sealed",
      "line": "One more stamp for the shelf. The trip is officially yours."
    },
    "postcard": {
      "narration": "Last card. Write something short and sweet, then let the sun set on this one.",
      "headline": "Wish you were here",
      "line": "Bali was loud, lovely, and full of tiny voices. Miss you all already."
    }
  },
  "awards": [
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000001",
      "title": "Earliest riser",
      "line": "Jordan started 3 early mornings, earliest at 02:51, that's 38% of the crew's 8."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000002",
      "title": "Treasurer",
      "line": "Rin logged 23 of 61 expenses, a cool 38% of the crew's receipts."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000003",
      "title": "Best find",
      "line": "Alex took the crew back to Warung Pondok 2 times, 40% of all 5 revisits."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000004",
      "title": "Planner",
      "line": "Wen made 14 of 20 plan edits, that's 70% of the crew's tinkering."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000005",
      "title": "Navigator",
      "line": "Maya logged 9 of 12 rides, 75% of the crew's wheel time."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000006",
      "title": "Good company",
      "line": "Dev, no numbers needed. Thanks for coming, terima kasih (thank you)."
    }
  ]
}
